<?php
require_once __DIR__ . '/_common.php';
$pdo=Database::getInstance(); [$input,$userId]=transactionRequest($pdo); $uuid=trim((string)($input['uuid']??''));
if (!preg_match('/^[a-f0-9-]{36}$/i',$uuid)) jsonResponse(['success'=>false,'error'=>'A valid transaction reference is required.'],422);
$stmt=$pdo->prepare("SELECT t.uuid,t.reference,t.type,t.status,t.currency_code,t.amount,t.fee_amount,t.provider,t.created_at,t.completed_at,p.customer_name,p.customer_email,p.status payment_status,card.last4,CASE WHEN ct.id IS NOT NULL THEN 'card' WHEN c.kind='crypto' OR t.type='swap' THEN 'crypto' WHEN JSON_UNQUOTE(JSON_EXTRACT(t.metadata,'$.channel'))='apple_pay' THEN 'apple_pay' ELSE 'bank_transfer' END channel FROM transactions t LEFT JOIN payments p ON p.transaction_id=t.id LEFT JOIN card_transactions ct ON ct.transaction_id=t.id LEFT JOIN cards card ON card.id=ct.card_id LEFT JOIN currencies c ON c.code=t.currency_code WHERE t.uuid=? AND t.user_id=? LIMIT 1"); $stmt->execute([$uuid,$userId]); $r=$stmt->fetch(); if(!$r) jsonResponse(['success'=>false,'error'=>'Transaction not found.'],404);
jsonResponse(['success'=>true,'transaction'=>['uuid'=>$r['uuid'],'reference'=>$r['reference'],'type'=>$r['type'],'status'=>transactionStatus($r['status'],$r['type'],$r['payment_status']??null),'currency'=>$r['currency_code'],'amount'=>(string)$r['amount'],'fee'=>(string)$r['fee_amount'],'net'=>(string)((float)$r['amount']-(float)$r['fee_amount']),'channel'=>$r['channel'],'provider'=>$r['provider']?:'Flowwithlit','customer_name'=>$r['customer_name']?:'—','customer_email'=>maskEmail($r['customer_email']??null),'card_last4'=>$r['last4']?:null,'created_at'=>$r['created_at'],'completed_at'=>$r['completed_at']]]);
